ays / shoulder months","green":"Deep off-holiday midweeks (softest domestic demand)","booking_lead":"Weeks–months for Semana Santa/summer/Christmas/long-weekend cabañas; midweek walk-up-easy; largely direct/domestic","event_peaks":"Semana Santa, summer school holidays, Christmas–New-Year, Mexican puentes","fire_date":"''Cool-mountain weekend from Guadalajara'' ahead of summer + Semana Santa; waterfall-flow (Oct–Dec) into fall"},"jewels":[{"name":"El Salto waterfall (Los Cazos)","si_tag":"Global Expedition Adventures","status":"future","hook":"~35 m waterfall, ~45-min forest hike (or horseback) to a wooden overlook","bookable_category":"site entry (~US$1) + guide/horse","tier":"essential","source":"https://www.zonaturistica.com/en/things-to-do/jalisco/mazamitla/the-salto-waterfall (Accessed 2026-07-04)","si":"expedition","blurb":"~35 m waterfall, ~45-min forest hike (or horseback) to a wooden overlook","commission":"day-tour or curated-recommend","accessed":"2026-07-04","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["expedition"],"shelf_fit":{"adventure":"destination","expedition":"primary","family":"destination"},"commission_lane":[],"commission_embedded":false,"commission_basis":"unparsed"},{"name":"La Zanja town forest","si_tag":"Global Expedition Adventures","status":"future","hook":"1977 municipal pine forest — trails, cabins, rentable grills","bookable_category":"free/low-cost","tier":"essential","source":"https://theguadalajarapost.com/2022/06/03/mazamitla-jalisco-what-to-do-and-how-to-get-to-this-magical-town/ (Accessed 2026-07-04)","si":"expedition","blurb":"1977 municipal pine forest — trails, cabins, rentable grills","commission":"curated-recommend","accessed":"2026-07-04","wells":["activities"],"wells_basis":"pass 2 — text","si_all":["expedition"],"shelf_fit":{"adventure":"destination","expedition":"primary","family":"destination"},"commission_lane":[],"commission_embedded":false,"commission_basis":"unparsed"},{"name":"Canop