-a-complete-guide-for-nature-lovers/","si":"wildlife","commission":"guide/DMC; entry non-commissionable","wells":[],"wells_basis":"text supports no Well — needs a human read","si_all":["wildlife"],"shelf_fit":{"expedition":"destination","romance":"destination","wildlife":"primary"},"commission_lane":["DMC","guide"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Curi-Cancha Reserve","si_tag":"wildlife","tier":"essential","source":"https://mytanfeet.com/activities/birdwatching-at-curi-cancha-reserve/","si":"wildlife","commission":"guide/DMC; entry non-commissionable","wells":[],"wells_basis":"text supports no Well — needs a human read","si_all":["wildlife"],"shelf_fit":{"expedition":"destination","romance":"destination","wildlife":"primary"},"commission_lane":["DMC","guide"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Bat Jungle","si_tag":"wildlife","tier":"essential","source":"https://monteverdecostarica-info.weebly.com/monteverde-bat-jungle.html","si":"wildlife","commission":"affiliate/pass-through","wells":[],"wells_basis":"text supports no Well — needs a human read","si_all":["wildlife"],"shelf_fit":{"expedition":"destination","romance":"destination","wildlife":"primary"},"commission_lane":["affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Butterfly Garden + glass-frog vivarium","si_tag":"wildlife","tier":"essential","source":"https://tours.co.cr/activities-in-monteverde/","si":"wildlife","commission":"affiliate/pass-through","wells":["activities"],"wells_basis":"pass 2 — text","si_all":["wildlife"],"shelf_fit":{"expedition":"destination","romance":"destination","wildlife":"primary"},"commission_lane":["affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Monteverde Cheese Factory (La Lecheria) + coffee","si_tag":"wildlife","tier":"essential","source":"https://www.costarica-spirit.com/destinations/monteverde/","si":"wildlife","commission":"DMC/guide add-on","wells":["eat"],"well