  ('nosara-costa-rica', '10S', 'Nosara & the Nicoya Peninsula', 'Costa Rica', 'Sunrise vinyasa over a Blue Zone shore', 'live', 'verified', 'tropicalBeach', 'Costa Rica', '{"tropical","expedition","wellness"}', '{"tropical"}', '{"essential","comfort","premier","luxury","ultra"}', null, null, '{"key_facts":["Nicoya Peninsula is Costa Rica''s Blue Zone — historically ~3-4x the global centenarian rate (2013 study).","Playa Guiones (Nosara) offers consistent year-round surf — Nosara sees 300+ surfable days a year.","Ostional Wildlife Refuge (est. 1984) hosts olive-ridley arribadas of up to ~500,000 turtles, peaking Sep-Oct.","Santa Teresa / Mal Pais is the peninsula''s boho-luxury surf-and-sunset coast, remote southern tip.","LIR (Liberia) is ~2.5-3 hr drive to Nosara; Tambor (TMU) is a 25-min flight + 25-min drive to Santa Teresa."],"safety":{"emergency":"911","book_enabled":true,"air_access_verified":true,"nearest_trauma":"Nicoya town hospital (stabilize) -> CIMA Guanacaste (Liberia) / CIMA San Jose (major) -> air evac ($20k-$100k+) for extreme trauma","advisory_reasons":["crime (petty + violent)","deadly rip currents"],"riptide":"STRONG at Playa Guiones & Santa Teresa; swim only in guarded/designated zones","activity_fires":["surf/riptides (beginner Guiones vs advanced Santa Teresa)","ATV/quad on unpaved roads (leading local injury)","turtle arribada (guided-only, no lights)","waterfall jumping (Montezuma)"],"road_remoteness_flag":"Santa Teresa/Mal Pais — unpaved sections, green-season river crossings, slow trauma response","dengue":"present, wet-season peak","water":"potable in developed towns; bottled/filtered common in remote beach communities — verify locally","fcdo":{"posture":"1","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/costa-rica","read":"2026-08-20T14:54:18Z","page_updated":"2026-05-19T11:42:25+01:00","source_country":"costa-rica","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"pos