  ('oaxaca-city-mexico', '10S', 'Oaxaca City & the Central Valleys', 'Mexico', 'High valley of mezcal and markets', 'live', 'verified', 'kyoto', 'Oaxaca (Oaxaca City & Coast)', '{"romance","expedition"}', '{}', '{"essential","comfort","premier","ultra"}', null, null, '{"key_facts":["Dual UNESCO World Heritage: Historic Centre of Oaxaca + Monte Alban, jointly inscribed 1987","Santiago Matatlan is the recognized World Capital of Mezcal, ~45 min SE on the Ruta Caminos del Mezcal","Teotitlan del Valle: ~2,500-year living Zapotec weaving tradition, natural cochineal/indigo/marigold dyes, rugs $75–$500","Tlacolula Sunday market: longest continuously running market in Mesoamerica, 1,000+ vendors","El Tule (Santa Maria del Tule): the world''s widest tree, a ~2,000-year-old Montezuma cypress"],"safety":{"emergency":"911","hospitals":["Clinica Hospital Carmen (Calle M. Abasolo 215)","Hospital Reforma (Calle Reforma 613)"],"medevac":"Air ambulance staged at OAX; serious cases transferred to Mexico City (MEX)","advisory_note":"Oaxaca City / Monte Alban / Puerto Escondido / Huatulco explicitly carry no US-gov-employee restrictions","book_enabled":true,"air_access_verified":true,"airport":"OAX (Xoxocotlan International)","altitude_m":1555,"altitude_note":"~1,550–1,555 m (mild)","water":"bottled/purified","other_risks":["Hierve el Agua cliff-edge footing + periodic Jun–Oct closures","high-proof mezcal + rural driving (use driver)","high-valley UV/heat on all-day circuits"],"fcdo":{"posture":"AREA-RESTRICTED","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-08-20T14:49:02Z","page_updated":"2026-07-16T16:08:09+01:00","source_country":"mexico","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely","fcdo_zones":[{"name":"The city of Tijuana, in Baja California","lvl":3,"posture":"all-but-essential","except":["airside transit through Tijuana airport","the Cross Border Xpress bridge linking the airport across the border","federal toll road 1D and the Via Rápida through Tijuana to the border"]},{"name":"The city of Tecate in Baja California, including roads between Tijuana and Tecate","lvl":3,"posture":"all-but-essential"},{"name":"The state of Chihuahua","lvl":3,"posture":"all-but-essential","except":["the city of Chihuahua","the border crossing in Ciudad Juárez via federal toll road 45","federal toll road 45D between Chihuahua and Ciudad Juárez","the Copper Canyon rail route and the towns immediately on it, including Creel","the road from Creel via San Juanito to San Pedro","state highway 16 from San Pedro to Chihuahua"],"note":"The advisory also covers the areas south-west of road 45D."},{"name":"The state of Sinaloa","lvl":3,"posture":"all-but-essential","except":["the cities of Los Mochis and Mazatlán","road 32 between El Fuerte and Los Mochis","the 15D federal toll road running the length of the state","the Copper Canyon rail route to and from Los Mochis and El Fuerte, and the towns immediately on it"]},{"name":"The state of Tamaulipas","lvl":3,"posture":"all-but-essential","except":["the border crossing at Nuevo Laredo via federal toll road 85D from Monterrey","federal highways 80, 81 and 85 between Tampico, Ciudad Victoria and Magueyes","the area of Tamaulipas south of those highways"]},{"name":"The state of Zacatecas","lvl":3,"posture":"all-but-essential"},{"name":"In Guanajuato: the areas south-west of road 45D","lvl":3,"posture":"all-but-essential","note":"FCDO advises against all but essential travel to the areas south-west of road 45D. (San Miguel de Allende and Guanajuato City sit outside this area.)"},{"name":"The state of Michoacán","lvl":3,"posture":"all-but-essential","except":["the city of Morelia via federal toll roads 15D, 126 and 43","toll road 48D between Morelia and its airport","the town of Pátzcuaro via toll roads 14D and 15 from Morelia, and boat trips on Lake Pátzcuaro","Federal Highway 15D"]},{"name":"In Jalisco: 