od-vs-fairmont-vs-andaz-vs-banyan-tree/"},{"name":"La Casa de la Playa (Grupo Xcaret)","price_tier":"ultra","virtuoso":true,"earning":"15% via Xcaret Agents Pro OR host-Virtuoso ($100 credit)","mor_posture":true,"source":"https://www.virtuoso.com/hotels/16561922/la-casa-de-la-playa"}],"source_verified":"2026-07-04","hero":{"query":"Playa del Carmen, Mexico"},"geo":{"lat":20.6296,"lng":-87.0739},"orbit":[{"id":"akumal-mexico","jewels":5,"si":["diveglobal","ocean","culture"]},{"id":"bacalar-mexico","jewels":6,"si":["tropical","wellness","adventure"]},{"id":"cancun-mexico","jewels":5,"si":["tropical","adventure","diveglobal","ocean"]},{"id":"coba-mexico","jewels":5,"si":["culture","expedition","family"]},{"id":"cozumel-mexico","jewels":5,"si":["diveglobal","liveaboard","ocean"]},{"id":"holbox-mexico","jewels":4,"si":["expedition","romance","ocean","wildlife"]},{"id":"isla-contoy-mexico","jewels":3,"si":["expedition","ocean","wildlife"]},{"id":"isla-mujeres-mexico","jewels":5,"si":["tropical","ocean","diveglobal","adventure"]},{"id":"mahahual-mexico","jewels":5,"si":["liveaboard","diveglobal"]},{"id":"puerto-aventuras-mexico","jewels":5,"si":["romance","diveglobal","ocean","wildlife"]},{"id":"puerto-morelos-mexico","jewels":5,"si":["diveglobal","ocean","adventure","culinary"]},{"id":"sian-kaan-mexico","jewels":5,"si":["expedition","wildlife","tropical"]},{"id":"tulum-mexico","jewels":5,"si":["expedition","diveglobal","culture","wildlife"]}],"orbit_country":["balandra-beach-mexico","cabo-pulmo-mexico","cabo-san-lucas-mexico","calakmul-mexico","campeche-city-mexico","careyes-mexico","celestun-mexico","chapala-ajijic-mexico","chichen-itza-mexico","costalegre-mexico","east-cape-mexico","ensenada-mexico","espiritu-santo-island-mexico","guadalajara-mexico","guanajuato-city-mexico","huatulco-mexico","izamal-mexico","la-paz-mexico","loreto-mexico","los-barriles-mexico","magdalena-bay-mexico","mazamitla-mexico","merida-mexico","mexico-city-mexico","oaxaca-city-mexico","palenque-